import{_ as r,o as e,c as i,b6 as a,bT as l,bU as o,bV as s,bW as n,bX as g,bY as d,bZ as b,b_ as h,b$ as p,c0 as c,c1 as m,c2 as _,c3 as u,c4 as A,c5 as I,c6 as f,c7 as k,c8 as P,c9 as x,ca as C,cb as v,cc as W,cd as V,ce as w,cf as U,cg as S,ch as D,ci as T,cj as y,ck as M,cl as L,cm as R,cn as E,co as G,cp as j}from"./chunks/framework.BUXTSoD9.js";const F=JSON.parse('{"title":"7つのAIプログラミングツールの比較","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md","filePath":"ja-jp/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"}'),K={name:"ja-jp/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"};function X(Z,t,N,q,z,$){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="_7つのaiプログラミングツールの比較" tabindex="-1">7つのAIプログラミングツールの比較 <a class="header-anchor" href="#_7つのaiプログラミングツールの比較" aria-label="Permalink to “7つのAIプログラミングツールの比較”">​</a></h1><h2 id="本章のガイド" tabindex="-1">本章のガイド <a class="header-anchor" href="#本章のガイド" aria-label="Permalink to “本章のガイド”">​</a></h2><p>数多くあるAIプログラミングツールの中で、どれが自分に一番合っているのでしょうか？本章では、統一された実践タスク——「スネークゲーム + AIで詩を作る」ゲームの開発——を通じて、Lovable、Replit、Z.aiなど7つの主要なWeb Vibe Codingプラットフォームを深く横断的に評価します。初心者へのやさしさ、コードの制御性、デプロイの便利さなど、複数の観点から比較し、あなたに最適な開発支援ツールの選び方をご案内します。</p><hr><h1 id="_1-vibe-codingでスネークゲームを作る-完全実践チュートリアル" tabindex="-1">1. Vibe Codingでスネークゲームを作る：完全実践チュートリアル <a class="header-anchor" href="#_1-vibe-codingでスネークゲームを作る-完全実践チュートリアル" aria-label="Permalink to “1. Vibe Codingでスネークゲームを作る：完全実践チュートリアル”">​</a></h1><p>本記事では、「Vibe Coding（雰囲気コーディング）」と呼ばれる新興のソフトウェア開発手法についてご紹介します。これは人工知能を活用してアプリケーション構築プロセスを加速させる手法です。</p><p>続いて、Vibe Codingの核心的な概念、AI Agentとは何かを説明し、実用的なプロンプトの書き方をご紹介します。最後に、ゼロから「スネーク（Snake）」ゲームを構築する完全な実践を通じて、複数の主要なVibe Codingプラットフォームを詳しく比較評価し、自分に最も適したツールの組み合わせを選べるようにします。</p><h2 id="ここで学べる内容" tabindex="-1">ここで学べる内容： <a class="header-anchor" href="#ここで学べる内容" aria-label="Permalink to “ここで学べる内容：”">​</a></h2><ul><li><strong>Vibe Codingとは何か：</strong> 定義、ワークフロー、そして主な利点について理解します。</li><li><strong>AI Agentの役割：</strong> AI Agentの動作方式、および従来のプログラムとの違いを理解します。</li><li><strong>プロンプトの上手な書き方：</strong> 明確で具体的なプロンプトの書き方を身につけ、より良い結果を得られるようになります。</li><li><strong>Vibe Codingツール：</strong> 主要なAIプログラミング・デザインプラットフォームを知ります。</li><li><strong>プラットフォームの比較：</strong> 初心者の視点から、7つの異なるAI Agentプラットフォームの長所と短所を評価・比較します。</li><li><strong>UI / UXツール：</strong> Figma、MastergoなどのUI/UXツールを全体のワークフローに組み込む方法を学びます。</li></ul><h2 id="_1-はじめに" tabindex="-1">1. はじめに <a class="header-anchor" href="#_1-はじめに" aria-label="Permalink to “1. はじめに”">​</a></h2><p>これまでのレッスンでは、z.aiのフルスタック開発モデルを使ってプログラミングタスクを進めてきました。</p><p>しかし、その核心が「AI Agent」であることはご存知でしょうか？（一般的なチャット式AIとは異なり、ずっとスマートです。）なぜなら、単に会話するだけでなく、思考（タスクを与えると、まず計画を立てます）し、自発的に行動（例えば、Web検索、PCコマンドの実行、Webページを開くなどのツールを呼び出す）できるからです。詳しくは後ほど説明します。</p><h2 id="_1-vibe-codingとは何か" tabindex="-1">1. Vibe Codingとは何か？ <a class="header-anchor" href="#_1-vibe-codingとは何か" aria-label="Permalink to “1. Vibe Codingとは何か？”">​</a></h2><p>Vibe Codingとは、AIを活用してアプリケーション開発プロセスを加速させる新しいソフトウェア開発手法です。従来のプログラミングの代替ではなく、より「対話型」のプログラミングモードと言えます。この概念はAI研究者のAndrej Karpathy氏によって提唱されました。このワークフローでは、開発者はコードを一行ずつ手書きするのではなく、主にAI Agentを誘導してアプリケーションの生成、最適化、デバッグを行います。</p><p>Vibe Codingの核心的な考え方は、<strong>「コード中心（code-first）」</strong>から<strong>「意図中心（intent-first）」</strong>への転換です。もう最初の一行からコードを考える必要はなく、自然言語で期待する結果を記述するだけで済みます。</p><p>典型的なVibe Codingのワークフローは、継続的なイテレーションのサイクルです：</p><ul><li><strong>目標を記述する：</strong> まず一文または一段落で実現したい機能を記述します。例：「Pythonバックエンド付きで、詩を生成できるシンプルなスネークゲームを作って。」</li><li><strong>AIがコードを生成：</strong> AI Agentがあなたのニーズを解析し、基本構造、フロントエンドページ、バックエンドロジックを含む初版コードを生成します。</li><li><strong>実行して確認：</strong> 生成されたコードを実行し、期待通りに動作するか確認します。同時にバグや不十分な点を見つけます。</li><li><strong>フィードバックして反復：</strong> エラーや期待通りの結果でない場合は、チャットで引き続き指示を出します。例：「蛇の移動が遅すぎるので、速度を上げてください」や「<code>.env</code>ファイルのAPI Keyが正しく読み込まれていません。バックエンドコードを修正してください。」</li><li><strong>上記の手順を繰り返す：</strong> 「記述 → 生成 → 実行 → フィードバック」のサイクルで継続的にイテレーションし、アプリケーションが満足できる状態になるまで続けます。</li></ul><h3 id="vibe-codingの主な利点" tabindex="-1">Vibe Codingの主な利点： <a class="header-anchor" href="#vibe-codingの主な利点" aria-label="Permalink to “Vibe Codingの主な利点：”">​</a></h3><ul><li><strong>敷居を下げる：</strong> プログラミング経験のないデザイナー、起業家、学生なども、自然言語でアプリケーション開発に参加できるようになります。</li><li><strong>迅速なプロトタイピング：</strong> アイデアから最小viable製品（MVP）までの時間が大幅に短縮されます。</li><li><strong>効率の向上：</strong> テンプレートコードなど、大量の反復的・機械的なコーディング作業を自動処理し、開発者がアーキテクチャ設計や問題の抽象化に注力できるようにします。</li><li><strong>実験に有利：</strong> まず迅速に成果物を作り、その後継続的に改良していくアプローチを奨励し、新しいアイデアや機能の試行がしやすくなります。</li></ul><h2 id="_2-vibe-codingオンラインプラットフォーム-web-based-とは何か" tabindex="-1">2. Vibe Codingオンラインプラットフォーム（Web-based）とは何か？ <a class="header-anchor" href="#_2-vibe-codingオンラインプラットフォーム-web-based-とは何か" aria-label="Permalink to “2. Vibe Codingオンラインプラットフォーム（Web-based）とは何か？”">​</a></h2><p>今回の実測では、評価するツールが<strong>Web-based（オンラインプラットフォーム）</strong>と<strong>IDE（ローカル開発環境）</strong>の2つのカテゴリーに分かれていることがわかります。</p><p>どちらも基本的にはAIにコードを書かせる仕組みですが、使用感と適用シーンには大きな違いがあります：</p><h3 id="vibe-codingオンラインプラットフォーム-web-based" tabindex="-1">Vibe Codingオンラインプラットフォーム (Web-based) <a class="header-anchor" href="#vibe-codingオンラインプラットフォーム-web-based" aria-label="Permalink to “Vibe Codingオンラインプラットフォーム (Web-based)”">​</a></h3><p><strong>代表的なツール：</strong> Lovable, Replit, Z.ai, v0</p><p>「荷物を持ってすぐ入居できる」サービス付きマンションのようなものです。</p><ul><li><strong>環境設定不要：</strong> Python環境やNode.jsのバージョン、依存パッケージのインストールなどを気にする必要はありません。ブラウザを開いてURLを入力するだけで、すぐにコーディングを始められます。</li><li><strong>ワンクリックプレビューとデプロイ：</strong> コードが生成されると、プラットフォームは通常、右側のウィンドウに自動的に実行結果を表示します。完成したら、ボタン一つでリンクを生成して友人に共有できます。</li><li><strong>適したシーン：</strong><ul><li><strong>アイデアの迅速な検証（MVP）：</strong> 頭の中にアイデアがあり、30分程度で試してみたい場合。</li><li><strong>初心者の入門：</strong> 複雑な環境エラーで挫折したくなく、AIプログラミングの楽しさを体験したい場合。</li><li><strong>軽量アプリケーション：</strong> シンプルなツールWebページ、ミニゲーム、個人ポートフォリオページなど。</li></ul></li></ul><h3 id="ai-ide-ローカル開発環境" tabindex="-1">AI IDE (ローカル開発環境) <a class="header-anchor" href="#ai-ide-ローカル開発環境" aria-label="Permalink to “AI IDE (ローカル開発環境)”">​</a></h3><p><strong>代表的なツール：</strong> Cursor, Trae, VS Code + AIプラグイン</p><p>「内装付き」の持ち家のようなものです。</p><ul><li><strong>強力なローカル能力：</strong> お使いのコンピュータ上で動作し、すべてのローカルファイルに直接アクセスでき、コンピュータの計算リソースを活用できます。</li><li><strong>プロのワークフローとシームレスに連携：</strong> 大規模プロジェクトに適しており、各種プラグインを自由にインストールし、ローカルデータベースに接続し、複雑なデバッグが可能です。</li><li><strong>適したシーン：</strong><ul><li><strong>プロジェクト開発：</strong> 長期メンテナンスが必要で、構造が複雑な商業プロジェクト。</li><li><strong>深いカスタマイズ：</strong> コードの細部を極限まで制御したい場合や、既存のローカルワークフロー（Git、Dockerなど）と深く統合する必要がある場合。</li><li><strong>データプライバシー：</strong> コードが完全にローカルにあり、企業のセキュリティ規範により適合します。</li></ul></li></ul><p><strong>まとめると：</strong> AIプログラミングに触れ始めたばかりの方や、手軽に小さなものを作ってみたい場合は、<strong>オンラインプラットフォーム</strong>が素晴らしい出発点です。プロの開発者の方や、プロジェクトが徐々に複雑になってきた場合は、<strong>ローカルIDE</strong>の方がより高い上限を提供してくれます。</p><hr><h2 id="_3-ai-agentとは何か" tabindex="-1">3. AI Agentとは何か？ <a class="header-anchor" href="#_3-ai-agentとは何か" aria-label="Permalink to “3. AI Agentとは何か？”">​</a></h2><h3 id="ai-agentとは何か" tabindex="-1">AI Agentとは何か？ <a class="header-anchor" href="#ai-agentとは何か" aria-label="Permalink to “AI Agentとは何か？”">​</a></h3><p>AI Agentとは、環境を認識し、意思決定を行い、特定の目標を達成するために自発的に行動できるソフトウェアシステムです。固定された指示に従い、単一のフローしか持たない従来のソフトウェアと比較して、AI Agentはより柔軟で適応性に優れています。</p><p>AI Agentを従来のプログラムと区別する主な特徴は以下の通りです：</p><ul><li><strong>自律性（Autonomy）：</strong> AI Agentは高い独立性を持っています。従来のプログラムは通常、人間が一歩一歩トリガーする必要がありますが、Agentは目標に基づいて次に何をすべきかを自ら判断できます。</li><li><strong>知覚と記憶（Perception &amp; Memory）：</strong> Agentは環境からデータを収集し（例：APIレスポンス、センサーデータ、ユーザー入力など）、「記憶」を通じてコンテキストを保持し、その後の行動で経験を再利用し、効果を継続的に改善します。</li><li><strong>合理性と目標志向（Rationality &amp; Goal-Orientation）：</strong> Agentは与えられた目標に基づいて分析と計画を行い、より高い「パフォーマンス指標」を追求するために最適な行動シーケンスを選択します。</li><li><strong>ツールの使用（Tool Use）：</strong> 近年のAI Agentの大きな特徴は、外部ツールを呼び出すことができ、「テキストの生成」にとどまらないことです。例えば、Webページの閲覧、コードの実行、データベースのクエリ、メールの送信などが可能で、「ツールを調整する」頭脳と言えます。</li></ul><p>このように例えて理解できます：</p><ul><li><strong>従来のプログラム</strong>は計算機のようなものです。数字と演算子を入力すると、ボタンを押した時にだけ計算を実行します。</li><li><strong>AIアシスタント</strong>は人間のアシスタントのようなものです。「近くのレストランを探して」と頼むと、検索結果を表示し選択肢を提示しますが、最終的な決定はあなたが行います。</li><li><strong>AI Agent</strong>は自動化された研究チームのようなものです。あなたは上位の目標（例：「日本旅行の計画を立てて」）を与えるだけで、Agentがタスクを分解し、インターネットで情報を調べ、航空券やホテルを予約し（API経由）、スケジュールを整理し、最終的に結果を届けてくれます。プロセスの細部にほとんど介入する必要はありません。</li></ul><hr><h1 id="_2-プロンプトの書き方について" tabindex="-1">2. プロンプトの書き方について <a class="header-anchor" href="#_2-プロンプトの書き方について" aria-label="Permalink to “2. プロンプトの書き方について”">​</a></h1><h2 id="_1-プロンプトは一度に書き上げる方が良いか、それとも複数ステップに分ける方が良いか" tabindex="-1">1. プロンプトは一度に書き上げる方が良いか、それとも複数ステップに分ける方が良いか？ <a class="header-anchor" href="#_1-プロンプトは一度に書き上げる方が良いか、それとも複数ステップに分ける方が良いか" aria-label="Permalink to “1. プロンプトは一度に書き上げる方が良いか、それとも複数ステップに分ける方が良いか？”">​</a></h2><p>多くの人は、「完全なフルスタックアプリケーションを作る」ことを一つのプロンプトで一度にまとめたくなるでしょう。事実、現在のツールは十分に強力であり、一見それなりの結果を一度に出すことも可能です。しかし、全体的な体験と成功率から見ると、作業を小さなステップに分け、段階的にイテレーションする方が、結果的に良い成果が得られやすく、「どうしても変えられない」という行き詰まりに陥りにくくなります。</p><blockquote><p><strong>ヒント：</strong> 「一発で完璧」を期待するより、大きな目標を一つずつ実行可能な小さなTo-doに分割しましょう。 例えば、「build me a Snake game」と直接言うのではなく、以下のように分けます： 「1. まずスネークゲームのフロントエンドを作る」、 「2. 次にスコアを記録するバックエンドを実装する」、 「3. 最後にフロントエンドとバックエンドを繋ぐ」。 こうすることで、AIがあなたのニーズをより正確に理解し、より信頼性の高い出力を提供してくれます。</p></blockquote><h2 id="_2-明確であればあるほど良い" tabindex="-1">2. 明確であればあるほど良い <a class="header-anchor" href="#_2-明確であればあるほど良い" aria-label="Permalink to “2. 明確であればあるほど良い”">​</a></h2><ul><li>Vibe Codingでは、あなたが書くプロンプトはコードと同じくらい重要です。プロンプトが明確で具体的であればあるほど、結果はあなたのイメージに近づきます。</li><li>最初に目標と制約条件を明確にしておけば、後の修正の回数を減らすことができます。これは時間の節約になるだけでなく、使用量とコストの節約にもなります。</li></ul><hr><h1 id="_3-ツールの概要-vibe-coding-uiuxツール" tabindex="-1">3. ツールの概要（Vibe Coding / UIUXツール） <a class="header-anchor" href="#_3-ツールの概要-vibe-coding-uiuxツール" aria-label="Permalink to “3. ツールの概要（Vibe Coding / UIUXツール）”">​</a></h1><h2 id="_1-ai-agentプラットフォーム" tabindex="-1">1. AI Agentプラットフォーム <a class="header-anchor" href="#_1-ai-agentプラットフォーム" aria-label="Permalink to “1. AI Agentプラットフォーム”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Name</strong></th><th><strong>Platform</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>Web-based</td></tr></tbody></table><h2 id="_2-ai-uiuxプラットフォーム" tabindex="-1">2. AI UIUXプラットフォーム <a class="header-anchor" href="#_2-ai-uiuxプラットフォーム" aria-label="Permalink to “2. AI UIUXプラットフォーム”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Name</strong></th><th><strong>Platform</strong></th></tr></thead><tbody><tr><td><strong><a href="https://mastergo.com/" target="_blank" rel="noreferrer">Mastergo</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.figma.com/" target="_blank" rel="noreferrer">FIgma</a></strong></td><td>Web-based, PC Plugin</td></tr></tbody></table><hr><h1 id="_4-実践チュートリアル-vibe-coding-uiの組み合わせ" tabindex="-1">4. 実践チュートリアル（Vibe Coding + UIの組み合わせ） <a class="header-anchor" href="#_4-実践チュートリアル-vibe-coding-uiの組み合わせ" aria-label="Permalink to “4. 実践チュートリアル（Vibe Coding + UIの組み合わせ）”">​</a></h1><ol><li><p>Vibe Codingを行うプラットフォームのチャットウィンドウで、作りたいプログラムの説明を入力します。 例：</p><blockquote><p>フロントエンドとバックエンドを備えたシンプルなスネーク（Snake）Webアプリケーションを構築してください。</p><ol><li>フロントエンド</li></ol><ul><li>ページ1：ゲームページ <ul><li>キーボードで蛇の移動を操作します。</li><li>蛇が食べるのは食べ物ではなく、英単語です。</li><li>ページのサイドバーに収集済みの単語とその数を表示します。</li><li>ゲームオーバー後も、収集済みの単語は保持され、新しいゲームにも引き継がれます。</li></ul></li><li>ページ2：詩を作るページ（Make Poem） <ul><li>ゲームページと同じ単語リストを表示します（データは同一）。</li><li>ボタンを提供し、現在収集している単語をバックエンドに送信して詩を生成します。</li><li>詩の生成後、使用された単語をリストから削除またはカウントを減らします。</li></ul></li></ul><ul><li>GameとMake Poemの2つのページ間を切り替えるためのシンプルなナビゲーションを追加してください。</li><li>収集した単語が両方のページで確認できるようにしてください。</li></ul><ol start="2"><li>バックエンド</li></ol><ul><li>収集した単語を受け取り、詩を返すバックエンドAPIを提供してください。</li><li>DeepSeek APIを使用して詩を生成します。</li><li>API Keyを<code>.env</code>ファイルに保存し、<code>.gitignore</code>でこのファイルを除外してください。</li></ul></blockquote></li><li><p>DeepSeek API Keyを入力します。（<a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">https://platform.deepseek.com/</a>で取得できます）</p><ol><li>LLMのAPI Keyは、あなた自身のプロジェクトで大規模言語モデルを呼び出すために使用します。これは機密情報であるため公開できず、設定ファイルに別途記載する必要があります。 <strong>なぜ<code>.env</code>ファイルを使い、GitHubにアップロードしてはいけないのか？</strong></li></ol><ul><li><code>.env</code>ファイルは<strong>鍵やパスワード</strong>（例：DeepSeek API Key）を保存するために特化しています。</li><li>このファイルがGitHubにアップロードされると、世界中の人があなたの鍵を見て不正使用する可能性があります。</li><li>安全のため、<code>.gitignore</code>ファイルで<code>.env</code>を除外するよう宣言し、Gitが追跡しないようにする必要があります。</li><li>これにより、プロジェクトはローカルでこれらの鍵を正常に使用しながら、リポジトリで鍵が漏洩することはありません。</li></ul></li><li><p>生成結果を確認した後、エラーや修正が必要な箇所があれば、チャットウィンドウで直接修正のリクエストを入力できます。</p></li><li><p>ページデザインに満足できない場合は、FigmaやMastergoでインターフェースを再設計し、そのデザインコンセプトをAgentにフィードバックすることもできます。</p></li></ol><ul><li><strong>例</strong></li></ul><blockquote><p><em>Word-Snake</em> という名前の<strong>2ページWebアプリケーション</strong>を設計してください。</p><ul><li><strong>Gameページ：</strong></li><li>蛇はキーボードで操作して移動します。</li><li>蛇が食べるのは通常の食べ物ではなく、英単語です。</li><li>右側のパネルに収集済みの単語と数を表示します。</li><li>ゲームオーバー後も、単語の在庫はリセットされず、次のラウンドに引き継がれます。</li><li><strong>Make Poemページ：</strong></li><li>同じ共有単語在庫を表示します。</li><li>ユーザーが一部の単語を選択し、<strong>Generate Poem</strong>ボタンをクリックします。</li><li>選択した単語をバックエンドに送信し、DeepSeek APIで詩を生成します。</li><li>詩の生成後、使用された単語を在庫から削除または減らします。</li><li><strong>ナビゲーション：</strong> シンプルなTabまたはトップメニューで2つのページ間を切り替えます。</li><li><strong>共有状態：</strong> 収集した単語が両方のページで常に同期され、確認できるようにします。</li></ul></blockquote><ul><li><strong>効果の例</strong></li></ul><p><img src="'+l+'" alt=""><img src="'+o+'" alt=""></p><hr><h1 id="_5-ai-agentプラットフォームの比較-シンプルなプロジェクトに最適な組み合わせの選び方" tabindex="-1">5. AI Agentプラットフォームの比較（シンプルなプロジェクトに最適な組み合わせの選び方） <a class="header-anchor" href="#_5-ai-agentプラットフォームの比較-シンプルなプロジェクトに最適な組み合わせの選び方" aria-label="Permalink to “5. AI Agentプラットフォームの比較（シンプルなプロジェクトに最適な組み合わせの選び方）”">​</a></h1><p>それぞれのVibe Codingプラットフォームには独自の特徴とワークフローがあります。私たちは同一の「DeepSeek APIを組み込んだスネークゲーム」という要件を使って、複数のプラットフォームで実測を行い、初心者の視点から長所と短所を評価しました。以下はそのまとめです。</p><h2 id="_1-比較基準" tabindex="-1">1. 比較基準 <a class="header-anchor" href="#_1-比較基準" aria-label="Permalink to “1. 比較基準”">​</a></h2><ol><li><p><strong>目標（Goal）</strong> DeepSeek APIに接続されたスネーク（Snake）Webアプリケーションを構築する。</p></li><li><p><strong>ゲームの詳細（Game Details）</strong></p><ol><li>ゲームはDeepSeek LLM APIを使用して詩を生成します。</li><li>蛇が食べるのは英単語で、収集された単語はゲーム終了後も保持され、新しいゲームでも引き続き使用されます。同じ単語は複数回収集でき、それぞれカウントされます。</li><li>詩が生成された後、使用された単語は在庫から削除されます。</li></ol></li><li><p><strong>必須機能（Must-Haves）</strong></p><ol><li>スネークゲームを含む実行可能なフロントエンドページ（キーボード操作、Canvasレンダリング）。</li><li>単語収集の仕組み（単語がボード上に表示され、蛇が単語を食べるとサイドバーのリストが更新される）。</li><li>複数ラウンドのゲーム間で単語在庫を永続化する機能。</li><li>DeepSeek APIを使用するバックエンド（API Keyがない場合は、まずモックの詩を返すようにする）。</li><li>「詩を生成する」ボタン：クリック後にバックエンドを呼び出し、詩を表示し、使用状況に応じて単語在庫を更新する。</li><li>API Keyに対する<code>.env</code>サポート、および<code>.gitignore</code>による鍵の漏洩防止。</li></ol></li><li><p><strong>加点要素（Nice-to-Haves）</strong></p><ol><li>ユーザーがどの単語を使って詩を生成するかを選択できる。</li><li>ユーザーエクスペリエンスが良い（例：サイドバーに単語リストが明確に表示される、詩の表示エリアのレイアウトが適切）。</li><li>初心者向けにコードにコメントを追加し、主要なロジックを説明している。</li></ol></li></ol><h2 id="_2-コーディング出力の比較" tabindex="-1">2. コーディング出力の比較 <a class="header-anchor" href="#_2-コーディング出力の比較" aria-label="Permalink to “2. コーディング出力の比較”">​</a></h2><h3 id="_1-lovable-web-based" tabindex="-1">1. Lovable（Web-based） <a class="header-anchor" href="#_1-lovable-web-based" aria-label="Permalink to “1. Lovable（Web-based）”">​</a></h3><ul><li><strong>プラットフォームタイプ：</strong> Web</li><li><strong>主な特徴とワークフロー：</strong> Lovableは統合とコラボレーションの面で優れています。Supabaseデータベースの接続などの初期化作業を自動的に完了し、プロジェクトのセットアッププロセスを非常にスムーズにします。プロジェクトの要件を記述するだけで、Agentが各種サービスを連携させ、基本構造を構築してくれます。</li><li><strong>対象ユーザー：</strong> 初めてVibe Codingに挑戦する初心者にとって、Lovableは非常に使いやすい選択肢です。複数サービス連携の複雑さを簡略化し、環境設定ではなくプロンプトとイテレーションに集中できます。高度な自動化のおかげで、すぐに実行可能なプロトタイプを得られます。</li><li><strong>プロンプトのプロセス：</strong><img src="'+s+'" alt=""></li><li><strong>スネークゲームの効果：</strong></li></ul><p><img src="'+n+'" alt=""><img src="'+g+'" alt=""></p><ul><li><strong>価格：</strong> 比較的高めですが、学校のメールアドレスがあれば、学生認証により半額で利用できます。 <img src="'+d+'" alt=""></li></ul><h3 id="_2-cursor-ide" tabindex="-1">2. Cursor（IDE） <a class="header-anchor" href="#_2-cursor-ide" aria-label="Permalink to “2. Cursor（IDE）”">​</a></h3><ul><li><strong>プラットフォームタイプ：</strong> デスクトップアプリケーション（PC）</li><li><strong>主な特徴とワークフロー：</strong> CursorはAI機能を統合した専用IDEで、Windows、macOS、Linuxに対応しています。コード生成、スマートリライト、コードベース検索などの機能を開発環境に直接組み込んでいます。Webツールと比較すると、より従来のローカル開発体験に近いです。ローカル環境であるため、コンピュータごとの設定が異なり、環境関連の問題に遭遇することがあります。メリットは、プロジェクトがローカルにあるため、追加で実行環境をダウンロード・設定する必要がなく、Cursorが多くの煩雑な手順を処理してくれることです。</li><li><strong>対象ユーザー：</strong> ある程度プログラミングの基礎があるユーザーにとって、Cursorは非常に強力で馴染みのある環境です。しかし、完全なゼロベースの初心者にとっては、プロジェクト構造、依存関係管理、ファイル編成などの概念を自分で理解する必要があり、学習曲線はやや急になります。従来のコーディングプロセスにAIアシスタントを加えたい開発者により適しています。</li><li><strong>プロンプトのプロセス：</strong><img src="'+b+'" alt=""></li><li><strong>スネークゲームの効果：</strong></li></ul><p><img src="'+h+'" alt=""><img src="'+p+'" alt=""></p><ul><li><strong>価格：</strong><img src="'+c+'" alt=""></li></ul><h3 id="_3-z-ai-web-based" tabindex="-1">3. Z.ai（Web-based） <a class="header-anchor" href="#_3-z-ai-web-based" aria-label="Permalink to “3. Z.ai（Web-based）”">​</a></h3><ul><li><strong>プラットフォームタイプ：</strong> Web</li><li><strong>主な特徴とワークフロー：</strong> Z.aiの使い方は比較的シンプルですが、明らかな課題が一つあります：<strong>生成されたコードを手動でコピー＆ペーストする</strong>必要があります。プラットフォーム自体にリアルタイムプレビューウィンドウがないため、コードの実行結果をすぐに確認するのが難しいです。</li><li><strong>対象ユーザー：</strong> このプラットフォームは比較的「手動」の使用方式を求めます。自動化が少ないため、コードと直接向き合う必要があり、AIの出力内容を深く理解したい人にとっては逆に良い訓練になります。しかし、頻繁なコピー＆ペーストは効率の問題とミスのリスクをもたらします。ワンクリック体験を追求する人ではなく、「生のAI出力コード」を見たい方に向いています。</li><li><strong>プロンプトのプロセス：</strong><img src="'+m+'" alt=""></li><li><strong>スネークゲームの効果：</strong></li></ul><p><img src="'+_+'" alt=""><img src="'+u+'" alt=""></p><ul><li><strong>価格：</strong><img src="'+A+'" alt=""></li></ul><h3 id="_4-replit-web-based" tabindex="-1">4. Replit（Web-based） <a class="header-anchor" href="#_4-replit-web-based" aria-label="Permalink to “4. Replit（Web-based）”">​</a></h3><ul><li><p><strong>プラットフォームタイプ：</strong> Web</p></li><li><p><strong>主な特徴とワークフロー：</strong> Replitはオールインワンのオンライン開発・デプロイ環境で、ブラウザ上でコーディング、プログラムの実行、オンラインアクセスURLの生成が可能です。コーディングを始める前に、明確なアクションプランを提示します。またビジュアルエディタも提供しており、プレビューウィンドウで直接UIを変更でき、ソースコードが自動的に同期更新されます。これにより、AIの出力が期待通りかどうかを随時確認でき、修正の往復を大幅に減らすことができます。</p><p><img src="'+I+'" alt=""></p></li><li><p><strong>対象ユーザー：</strong> Replitは初心者に非常に使いやすいです。コーディングからデプロイまでの完全なサイクルを簡略化し、自前でサーバーやホスティングサービスを設定する必要がありません。コラボレーション機能も強力で、同級生と一緒にプロジェクトを作ったり、他の人にリモートでコードを見てもらうのに適しています。</p></li><li><p><strong>プロンプトのプロセス：</strong> 構築中、AIは最初から要件を完全に理解しているわけではなく、約3ラウンドのイテレーションを経て、最終的に理想的な結果に到達しました。 <img src="'+f+'" alt=""></p></li><li><p><strong>スネークゲームの効果：</strong></p></li></ul><p><img src="'+k+'" alt=""><img src="'+P+'" alt=""></p><ul><li><strong>価格：</strong><img src="'+x+'" alt=""></li></ul><h3 id="_5-minimax-web-based" tabindex="-1">5. Minimax（Web-based） <a class="header-anchor" href="#_5-minimax-web-based" aria-label="Permalink to “5. Minimax（Web-based）”">​</a></h3><ul><li><strong>プラットフォームタイプ：</strong> Web</li><li><strong>主な特徴とワークフロー：</strong> Minimaxはタスクの実行に通常かなり時間がかかります。そのプロセスには、AIが自動的にエラーを発見して修正することが多く含まれるため、全体として遅く、やや手間がかかる印象です。本プロジェクトを例にすると、Agentは通常まず詳細な計画を作成し、その後ステップバイステップでバックエンド、データベース、フロントエンドのロジックを構築していきます。</li><li><strong>対象ユーザー：</strong> 自動的にテストを実行しエラーを修正するため、時間とTokenの消費が大きいですが、AIがどのように問題を特定し解決するかを明確に観察でき、学習の観点からは非常に価値があります。</li><li><strong>プロンプトのプロセス：</strong></li></ul><p><img src="'+C+'" alt=""><img src="'+v+'" alt=""><img src="'+W+'" alt=""><img src="'+V+'" alt=""></p><ul><li><strong>スネークゲームの効果：</strong></li></ul><p><img src="'+w+'" alt=""><img src="'+U+'" alt=""></p><ul><li><strong>価格：</strong> 無料版では複雑なプロジェクトを最初から最後までスムーズに完了するのが難しい場合があるため、プロジェクトを完全に構築できるよう、有料プランへのアップグレードをお勧めします。 <img src="'+S+'" alt=""></li></ul><h3 id="_6-trae-ide" tabindex="-1">6. Trae（IDE） <a class="header-anchor" href="#_6-trae-ide" aria-label="Permalink to “6. Trae（IDE）”">​</a></h3><ul><li><strong>プラットフォームタイプ：</strong> デスクトップアプリケーション（PC）</li><li><strong>主な特徴とワークフロー：</strong> デスクトップアプリケーションとして、TraeはWebツールと比較してパフォーマンスとレスポンス速度で通常優位性があります。ただし、ダウンロードとインストールが必要で、一部のユーザーにとっては導入の敷居が少し高くなります。同様に、ローカル環境であるため、コンピュータの設定や依存環境の違いにより、ある程度の不確実性が生じます。メリットは、Traeがローカルでのプロジェクト作成と実行設定を支援し、直接ローカルで開発とデバッグができることです。</li><li><strong>対象ユーザー：</strong> 長期的にVibe Codingプロジェクトを行い、専用のデスクトップツールを使用したいと考えているユーザーにより適しています。「たまに遊んでみたい」だけの方には、最も軽量な選択肢ではないかもしれません。</li><li><strong>プロンプトのプロセス：</strong><img src="'+D+'" alt=""></li><li><strong>スネークゲームの効果：</strong></li></ul><p><img src="'+T+'" alt=""><img src="'+y+'" alt=""></p><ul><li><strong>価格：</strong> 価格は比較的手頃で、無料版でも品質の良い小規模プロジェクトを十分に完了できます。 <img src="'+M+'" alt=""></li></ul><h3 id="_7-v0-web-based" tabindex="-1">7. V0（Web-based） <a class="header-anchor" href="#_7-v0-web-based" aria-label="Permalink to “7. V0（Web-based）”">​</a></h3><ul><li><p><strong>プラットフォームタイプ：</strong> Web</p></li><li><p><strong>主な特徴とワークフロー：</strong> V0はVercelが提供する、React UIコンポーネントの生成に特化したツールです。高品質で本番環境に使用可能なインターフェースの生成において優れたパフォーマンスを発揮します。ただし実際の使用では、「コードビューが見つけにくい」「API Keyをどこに設定すべきかの明確な説明がない」といった問題に直面することがあります。</p></li><li><p><strong>対象ユーザー：</strong> V0はフロントエンドとUI/UXデザインに注力する学生やデザイナーに非常に適しています。しかし完全なフルスタックソリューションではなく、バックエンドロジックとAPI統合を実装するには他のプラットフォームを使用する必要があるため、「ワンストップで完全なアプリケーションを構築する」ことが目標であれば、最適な第一選択ではないかもしれません。</p></li><li><p><strong>プロンプトのプロセス：</strong><img src="'+L+'" alt=""></p><p><img src="'+R+'" alt=""></p></li><li><p><strong>スネークゲームの効果：</strong><img src="'+E+'" alt=""><img src="'+G+'" alt=""></p></li><li><p><strong>価格：</strong> 無料ユーザーは約4〜5個のシンプルなプロジェクトを構築できます。 <img src="'+j+'" alt=""></p></li></ul><h2 id="_3-プラットフォームの総合比較" tabindex="-1">3. プラットフォームの総合比較 <a class="header-anchor" href="#_3-プラットフォームの総合比較" aria-label="Permalink to “3. プラットフォームの総合比較”">​</a></h2><table tabindex="0"><thead><tr><th><strong>プラットフォーム</strong></th><th><strong>レビュー</strong></th><th><strong>Platform</strong></th><th><strong>備考</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>AIプログラミング初心者に非常にやさしく、操作がシンプルで体験がスムーズ。理想的な入門選択。</td><td>Web-based</td><td>Supabaseなどのサービス接続を自動的に完了し、設定コストを削減。</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>開発経験のあるユーザーに適しており、生産性とコード品質を大幅に向上。</td><td>PC</td><td>ある程度のプログラミング基礎が必要。ローカル環境ではプロジェクト構造や依存関係を自分で理解する必要がある。</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>プログラミングの基礎があり、AI出力コードの細部を直接研究したいユーザーにより適している。</td><td>Web-based</td><td>プレビューウィンドウがなく、結果の確認が面倒。コードの手動貼り付け、フォルダやファイルの手動作成、サービスの手動実行が必要。</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>アイデアを素早くアクセス可能なオンラインサービスにしたいユーザーにお勧め。</td><td>Web-based</td><td>オールインワンのオンライン開発・デプロイ。コラボレーション対応、ビジュアルエディタ付き。</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>AIの自動的なエラー検出と修正の全プロセスを見て学びたい人に適しているが、全体として遅くToken消費が大きい。</td><td>Web-based</td><td>全プロセスが長く、AIが複数回自動テストを実行してエラーを修正する。</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>プログラミング経験があり、デスクトップIDE + AI Agentの組み合わせを使いたいユーザー向けの効率向上ツール。</td><td>PC</td><td>ローカルインストールと環境設定が必要だが、パフォーマンスが良く、長期的なVibe Codingプロジェクトに適している。</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>React UIの視覚効果を素早く作りたい非開発者向けに最適化。フロントエンド/デザイン志向の学生に適している。</td><td>Web-based</td><td>React UI生成に特化。バックエンドや完全なアプリケーション構築には他のプラットフォームとの連携が必要。</td></tr></tbody></table>',95)])])}const O=r(K,[["render",X]]);export{F as __pageData,O as default};
